<script setup>import {Head,Link,usePage} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Button from '@/Components/UI/Button.vue';import Icon from '@/Components/UI/Icon.vue';defineOptions({layout:AppLayout});defineProps({report:Object,filters:Object});const page=usePage();</script><template><Head title="Rapport RH à imprimer"/><div class="mx-auto max-w-5xl space-y-3"><div class="print-actions flex justify-between"><Button :as="Link" href="/administration/reports" size="rg" variant="white-outline"><Icon name="arrow-left"/><span class="ms-2">Retour</span></Button><Button size="rg" @click="window.print()"><Icon name="printer"/><span class="ms-2">Imprimer</span></Button></div><article class="print-doc bg-white p-8 text-slate-900"><header class="flex justify-between border-b-2 border-slate-900 pb-4"><div><strong class="uppercase">{{page.props.site?.brand||'Clinique Saint Georges'}}</strong><p class="text-xs">Site {{page.props.site?.name||''}}</p></div><div class="text-end"><h1 class="text-xl font-black uppercase">Rapport ressources humaines</h1><p class="text-xs">Du {{filters.from}} au {{filters.to}}</p></div></header><div class="mt-8 grid grid-cols-2 gap-3 text-sm"><p v-for="(value,key) in report.summary" :key="key" class="border border-slate-300 p-3"><strong>{{key.replaceAll('_',' ')}} :</strong> {{value}}</p></div><h2 class="mt-8 border-b border-slate-500 pb-1 text-sm font-black uppercase">Effectif par département</h2><table class="mt-3 w-full text-sm"><tr v-for="item in report.by_department" :key="item.uuid"><td class="border-b border-slate-200 py-2">{{item.label}}</td><td class="border-b border-slate-200 py-2 text-end font-bold">{{item.count}}</td></tr></table></article></div></template><style>@media print{.print-actions,aside,nav{display:none!important}.print-doc{padding:0!important}}</style>
